// Content with portions generated by generative AI platform
package org.eclipse.kura.web.server.util;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import org.eclipse.kura.configuration.ConfigurableComponent;
import org.eclipse.kura.driver.Driver;
import org.junit.Test;
import org.osgi.service.component.runtime.dto.ComponentDescriptionDTO;

public class FactoryPidCheckTest {

    private static final String COMPONENT_NAME = "org.example.driver.ExampleDriver";
    private static final String CONFIGURATION_PID = "org.example.driver.ExampleDriverConfiguration";

    private final ComponentDescriptionDTO component = new ComponentDescriptionDTO();
    private boolean accepted;
    private List<String> driverFactoryPids;

    @Test
    public void componentNameIsAcceptedAsFactoryPid() {
        givenDriverComponent();

        whenFactoryPidIsChecked(COMPONENT_NAME);

        thenFactoryPidIsAccepted();
    }

    @Test
    public void configurationPidIsAcceptedAsFactoryPid() {
        givenDriverComponent();
        givenConfigurationPids(CONFIGURATION_PID);

        whenFactoryPidIsChecked(CONFIGURATION_PID);

        thenFactoryPidIsAccepted();
    }

    @Test
    public void listedDriverFactoryPidIsAccepted() {
        givenDriverComponent();
        givenConfigurationPids(CONFIGURATION_PID);

        whenListedDriverFactoryPidIsChecked();

        thenListedDriverFactoryPidIs(CONFIGURATION_PID);
        thenFactoryPidIsAccepted();
    }

    @Test
    public void anyOfSeveralConfigurationPidsIsAccepted() {
        givenDriverComponent();
        givenConfigurationPids("org.example.driver.Other", CONFIGURATION_PID);

        whenFactoryPidIsChecked(CONFIGURATION_PID);

        thenFactoryPidIsAccepted();
    }

    @Test
    public void componentNameIsStillAcceptedWithAnotherConfigurationPid() {
        givenDriverComponent();
        givenConfigurationPids(CONFIGURATION_PID);

        whenFactoryPidIsChecked(COMPONENT_NAME);

        thenFactoryPidIsAccepted();
    }

    @Test
    public void unknownFactoryPidIsRejected() {
        givenDriverComponent();
        givenConfigurationPids(CONFIGURATION_PID);

        whenFactoryPidIsChecked("org.example.driver.Unknown");

        thenFactoryPidIsRejected();
    }

    @Test
    public void declaredServicePidThatIsNotAConfigurationPidIsRejected() {
        givenDriverComponent();
        givenProperty("service.pid", "org.example.driver.LegacyDriver");

        whenFactoryPidIsChecked("org.example.driver.LegacyDriver");

        thenFactoryPidIsRejected();
    }

    @Test
    public void configurationPidOfAnotherKindOfComponentIsRejected() {
        givenComponentProviding(ConfigurableComponent.class.getName());
        givenConfigurationPids(CONFIGURATION_PID);

        whenFactoryPidIsChecked(CONFIGURATION_PID);

        thenFactoryPidIsRejected();
    }

    private void givenDriverComponent() {
        givenComponentProviding(Driver.class.getName(), ConfigurableComponent.class.getName());
    }

    private void givenComponentProviding(final String... serviceInterfaces) {
        this.component.name = COMPONENT_NAME;
        this.component.serviceInterfaces = serviceInterfaces;
        this.component.configurationPolicy = "require";
        this.component.properties = new HashMap<>();
    }

    private void givenConfigurationPids(final String... configurationPids) {
        this.component.configurationPid = configurationPids;
    }

    private void givenProperty(final String key, final Object value) {
        this.component.properties.put(key, value);
    }

    private void whenFactoryPidIsChecked(final String factoryPid) {
        this.accepted = GwtServerUtil.isFactoryOf(
                Collections.singletonList(this.component), factoryPid, s -> s.contains(Driver.class.getName()));
    }

    private void whenListedDriverFactoryPidIsChecked() {
        this.driverFactoryPids =
                GwtComponentServiceInternal.getDriverFactoryPids(Collections.singletonList(this.component));

        whenFactoryPidIsChecked(this.driverFactoryPids.get(0));
    }

    private void thenListedDriverFactoryPidIs(final String expectedFactoryPid) {
        assertEquals(Collections.singletonList(expectedFactoryPid), this.driverFactoryPids);
    }

    private void thenFactoryPidIsAccepted() {
        assertTrue(this.accepted);
    }

    private void thenFactoryPidIsRejected() {
        assertFalse(this.accepted);
    }
}
